-- GENERATED by `wfj generate` from data/gossip/gossip-c0.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["c003798f24275740"] = { "Eh? La banca la trovi a Orgrimmar. Prendi la strada verso nord per arrivarci e poi parla con uno dei loro grunt.", "." },
  ["c00500d5c6a754a6"] = { "Un tempo accoglievo l'oscurità, perché era sorella della notte. Ora è sempre buio, anche di giorno, e le foreste invocano nutrimento. Se non agiamo presto, questa piaga che si diffonde coprirà il mondo.", "." },
  ["c005b1e7042aabe7"] = { "Dove vai? Beh, se vuoi arrivarci in fretta, sei nel posto giusto!", "." },
  ["c00cf61c1cfcf1cf"] = { "Duke of Zephyrs! Possiedo il tuo sigillo! Rispondi al mio richiamo!", "." },
  ["c00dcafacaf05171"] = { "Posso mostrarti cosa ho in vendita?", "." },
  ["c00e4886cb86bf0e"] = { "Ma guarda, <un/una> {class} giovane e <impetuoso/impetuosa>, senza dubbio <attirato/attirata> qui dai racconti delle mie imprese sui campi di battaglia!\n\nNon c'è tempo per le storie, ora: ci sono grandi e importanti imprese da compiere! Quindi, se cerchi la gloria, oggi la fortuna ti sorride...", "." },
  ["c00e81c6b2b84d3b"] = { "Ah! Finalmente aria fresca! Non pensavo che avrei visto questo giorno...", "." },
  ["c01df2286aff3eba"] = { "%s cerca un'anima da divorare!", "." },
  ["c01e7f699e3315a8"] = { "Grazie mille, {name}!", "." },
  ["c01f0607e842281c"] = { "Nella ⟦Silverpine Forest=Selva Pinargento⟧, lungo la ⟦North Tide's Run=Costa della Marea del Nord⟧, una barca abbandonata giace sulla riva. A ovest di essa si trova ciò che cerchi; se nuoti troppo lontano, l'oceano ti schiaccerà con la fatica. Riposa sul fondale, in uno scrigno chiuso, in attesa che tu lo reclami.\n\nSarà dura sopravvivere a un'immersione a tali profondità senza aiuto, ma fatti coraggio: una fenditura gorgogliante offre nuovo fiato a chi si immerge in cerca di questa metà del ciondolo. Usala con saggezza.", "." },
  ["c0221279c87311e6"] = { "A proposito, grazie per avermi coperto le spalle.", "." },
  ["c02faf632a8cf7b7"] = { "Voglio provarci, ma avrò bisogno di istruzioni.", "." },
  ["c055e1dda330d27d"] = { "Perché non vediamo di cosa sei capace? Se porti a termine il compito, proseguirò volentieri il tuo addestramento!", "." },
  ["c05ccf9b831fab75"] = { "Non lasciarti imbrogliare dagli umani del Bazar, <ragazzo/ragazza>: con il tram che hanno costruito quegli gnomi, trasportare merci da ⟦Ironforge=Forgiardente⟧ è più facile di quanto pensi. Se provano ad aggiungere dazi d'importazione, digli che comprerai la tua roba da me.", "." },
  ["c064fe05df6d0302"] = { "Spazzagli la gamba... Hai qualche problema con questo?", "." },
  ["c0654bd7d44bf625"] = { "Ho perso il mio ⟦Cloak of the Unseen Path=Mantello del Sentiero Invisibile⟧. Puoi sostituirmelo?", "." },
  ["c0679703d482a68a"] = { "Ascolta le storie di un anziano, {name}. Ne ho molte da raccontare...", "." },
  ["c068094d09f9e091"] = { "È difficile immaginare che tanta morte e disperazione possano essere racchiuse in un'area così piccola; eppure oltre la palude c'è una terra flagellata dal caos e dalla distruzione.\n\nGuarda dove metti i piedi, <avventuriero/avventuriera>. Le ⟦Blasted Lands=Terre Devastate⟧ sono l'ultima dimora di esseri ben più grandi di te.", "." },
  ["c06f6b683854899b"] = { "Alle ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ serve tutto l'aiuto possibile nella lotta contro i ⟦Warsong Outriders=Predoni Cantaguerra⟧. {name}, va' al Castello di ⟦Stormwind=Roccavento⟧ e parla con Elfarran, se vuoi aiutarle.", "." },
  ["c072ab6285231085"] = { "Sarà fatto.", "." },
  ["c073a98356d5d920"] = { "Mi dispiace, ma hai già imparato tutto ciò che so. L'elfo della notte Faldron però potrebbe addestrarti ancora. Cercalo nella ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧ di Darnassus.", "." },
  ["c0770bb7cca1c43e"] = { "E questo spiegherebbe perché te ne stai seduto in una cella in fondo a una montagna, giusto, nano?", "." },
  ["c078402cfa088a7b"] = { "Hai trovato altre loro pergamene? Se riesci a trovarle, dovrei poter ricostruire un quadro più ampio del culto.", "." },
  ["c07915695ecee073"] = { "Attenti! Ci sta attaccando {name}!", "." },
  ["c0795d5059b0c2ee"] = { "Gorzeeki, vorrei fare un acquisto.", "." },
  ["c0846f51085c2bca"] = { "Miei servitori...", "." },
  ["c08b3e3b16b408b2"] = { "Ci hai preso la mano. Non posso insegnarti altro, ma parla con Arthur Moore, un Reietto che lavora nel ⟦Rogues' Quarter=Quartiere dei Ladri⟧ di ⟦Undercity=Sepulcra⟧. Digli che ti mando io.", "." },
  ["c08db9f3264bebe7"] = { "L'infernale è uno dei demoni più potenti che uno stregone possa sperare di avere al proprio fianco in battaglia. La creatura è forte, ben corazzata e infligge colpi devastanti a qualsiasi nemico. Se scegliessi di infondere lo spirito di un infernale nella tua arma, otterresti alcuni di questi vantaggi: più Salute, rigenerazione e simili.\n\nSe vuoi saperne di più sui vilsegugi, dovresti parlare con Wytula, di fronte a me.", "." },
  ["c090c49a62713ac3"] = { "Guardatevi! È il più patetico tentativo di menare la spada che abbia mai visto!", "." },
  ["c0919f47ef59ef8b"] = { "Sembra che ti serva aiuto. Come posso aiutarti?", "." },
  ["c092baaaf9b9a4ea"] = { "Finalmente la mia anima può riposare... Oh, carissimo Cerellean...", "." },
  ["c099e60230592a58"] = { "Beh, ecco cosa mi succede a dormire troppo!", "." },
  ["c0a2dcd3a8c80a86"] = { "Tirami fuori di qui!", "." },
  ["c0a765196ada21e4"] = { "I Jeztor's Riders sono pronti! Soldati dell'⟦Horde=Orda⟧, presentatevi per il servizio!", "." },
  ["c0abad2ffbaa7ba2"] = { "Benvenuti tutti al più grande spettacolo di tutta Azeroth... la ⟦Darkmoon Faire=Fiera di Lunacupa⟧! Avventura ed emozioni vi attendono, non siate timidi! Misteri e premi per grandi e piccini sono qui da conquistare. E non dimenticate di parlare con il professore di tutte le Carte di Lunacupa che avete trovato durante i vostri viaggi!", "." },
  ["c0ada2bb21fedd5c"] = { "Io rappresento la forza che ti sostiene nei tuoi primi passi da <druido/druida>. Sei <venuto/venuta> da me per apprendere questa forza, e io te la insegnerò. Ti insegnerò tutto ciò che è l'orso spirituale, purché tu sappia ascoltare e comprendere.\n\nPer sapere cosa significa attingere al mio spirito, devi capire l'importanza della forza del corpo, così come della forza del cuore.", "." },
  ["c0b2853ca618f693"] = { "⟦Shadowfang Keep=Forte di Zannascura⟧", "." },
  ["c0b4f7163497cf17"] = { "Il progetto della verga è semplice. Dartol non ha usato la sua conoscenza arcana per crearla... è di natura più druidica.", "." },
  ["c0bef7ee420e4092"] = { "Ah, sentite la magia che filtra nella caverna, miei piccoli elfi... muhahaha.", "." },
  ["c0c2837aaa278d88"] = { "Nel tubo, 5 su 5!", "." },
  ["c0cc02a0ea309137"] = { "Curioso... Windsor, in questa visione, sei sopravvissuto? Lo chiedo solo perché una cosa che posso e voglio garantire è la tua morte. Qui e ora.", "." },
  ["c0d243567a74b54c"] = { "Buoni risparmi di stagione a te e ai tuoi cari!", "." },
  ["c0d2698542b8a70a"] = { "⟦Polar Tunic=Giubba Polare⟧.", "." },
  ["c0d4299e60bbdef8"] = { "Salve, {class}. Non ti ho visto di recente a un raduno esclusivo? Hai un'aria familiare, ma d'altronde questa città è un posto affollato.\n\nSe hai partecipato a quel convegno, di sicuro ti hanno dato un codice segreto. Dimmi il tuo codice e in cambio ti darò un premio speciale.", "." },
  ["c0d858998362fda2"] = { "Insegnami a preparare e applicare una ⟦Heavy Runecloth Bandage=Benda Pesante di Telarunica⟧, dottore.", "." },
  ["c0d89e006589bdb4"] = { "Noi, i troll Zandalari, siamo giunti qui da isole lontane, perché non possiamo ignorare la minaccia che ora incombe sul nostro mondo.", "." },
  ["c0e26b50e8e5bda1"] = { "Salute, soldato. L'intelligence riferisce che i troll Asciafredda a ovest hanno fatto prigioniero un maestro ingegnere goblin. Forse dovresti indagare?", "." },
  ["c0e44c2848bbb57f"] = { "Hai visto gli elementali dell'acqua contaminati nel nostro lago, {name}? È uno spettacolo pietoso, ma non so da dove vengano.\n\nIl tuo nome è stato fatto in passato, forse potresti aiutarmi con questo problema.\n\nLa prima cosa da scoprire è chi controlla questi elementali.", "." },
  ["c0e6f0c234226241"] = { "Supremo Mok'Morokk capo. Tu fa quello che io dico.", "." },
  ["c0edc0dcac804c69"] = { "Il mio popolo è a pezzi come la reliquia che cerchi di riparare.", "." },
  ["c0ede490704c456c"] = { "Rifornimenti dei nostri nemici! Ben fatto, {name}!", "." },
  ["c0f96139cffe96b4"] = { "Ne ho la certezza al 100%: voglio imparare le vie dell'Ingegneria degli Gnomi.", "." },
  ["c0ffbdc4607f9639"] = { "Dannazione! Vedi di non morirmi tra le mani, umano!", "." },
})
